-- 既有库定向升级；不属于新空库安装链。先确认目标、备份、停写及执行授权。
-- 不更新历史政策/审批/候选快照；升级后各实验室须整份保存政策。
-- 遇错停止，不用 --force。DDL不能整包回滚。
SET NAMES utf8mb4;
SELECT DATABASE() AS target_database, VERSION() AS target_version;
DELIMITER //
CREATE PROCEDURE m06_scene_catalog_precheck()
BEGIN
  IF DATABASE() IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Select and verify target database first';
  END IF;
  IF (SELECT COUNT(*) FROM apr_scene) <> 48 OR EXISTS (
    SELECT 1 FROM apr_scene WHERE scene_code NOT REGEXP '^M06_SC0(0[1-9]|[1-3][0-9]|4[0-8])$'
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Expected original 48 scene identities; inspect directory before upgrade';
  END IF;
END//
DELIMITER ;
CALL m06_scene_catalog_precheck();
DROP PROCEDURE m06_scene_catalog_precheck;
